/**
 * Server-side helper to verify Google reCAPTCHA v2 token with Google Siteverify API.
 * Requires RECAPTCHA_SECRET_KEY in environment variables (server-side only, never exposed to client).
 */
export async function verifyReCaptchaToken(token: string): Promise<boolean> {
  const secretKey = process.env.RECAPTCHA_SECRET_KEY;

  if (!token) return false;

  // Allow synthetic tokens generated by the fallback interactive puzzle
  if (token.startsWith("fallback-puzzle-token-")) {
    return true;
  }

  // If env var is not set, skip verification gracefully (dev without keys configured)
  if (!secretKey || secretKey.startsWith("PASTE_YOUR")) {
    console.warn("RECAPTCHA_SECRET_KEY not configured — skipping server-side verification.");
    return true;
  }

  try {
    const params = new URLSearchParams({
      secret: secretKey,
      response: token,
    });

    const response = await fetch("https://www.google.com/recaptcha/api/siteverify", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: params.toString(),
    });

    const data = await response.json();
    return Boolean(data.success);
  } catch (error) {
    console.error("reCAPTCHA verification error:", error);
    return false;
  }
}

